import { createHash } from "node:crypto";

/** A single deterministic item projected from a Working Context snapshot. */
export type ContextPressureRecoveryItem = string | Record<string, unknown>;

/** The subset of the existing Working Context snapshot consumed by recovery. */
export interface WorkingContextSnapshot {
  goal?: ContextPressureRecoveryItem | ContextPressureRecoveryItem[];
  unfinishedWork?: ContextPressureRecoveryItem | ContextPressureRecoveryItem[];
  dependencies?: ContextPressureRecoveryItem | ContextPressureRecoveryItem[];
  recentEvidence?: ContextPressureRecoveryItem | ContextPressureRecoveryItem[];
  depth?: number;
  handoffDepth?: number;
}

export interface ContextPressureRecoveryOptions {
  /** Maximum permitted Working Context/handoff depth. */
  maxDepth?: number;
  /** Maximum retained items per section. */
  maxItemsPerSection?: number;
  /** Maximum retained items across all four sections. */
  maxItems?: number;
}

export interface ContextPressureRecoverySection {
  items: ContextPressureRecoveryItem[];
  kept: number;
  dropped: number;
}

export interface ContextPressureRecoveryResult {
  status: "recovered" | "unknown" | "depth-exceeded";
  recovered: boolean;
  complete: false;
  truncated: boolean;
  sections: {
    goal?: ContextPressureRecoverySection;
    unfinishedWork?: ContextPressureRecoverySection;
    dependencies?: ContextPressureRecoverySection;
    recentEvidence?: ContextPressureRecoverySection;
  };
  counts: {
    total: number;
    kept: number;
    dropped: number;
    bySection: Record<"goal" | "unfinishedWork" | "dependencies" | "recentEvidence", number>;
  };
  digest: string;
  reason?: "empty-snapshot" | "depth-exceeded";
}

const SECTION_NAMES = [
  "goal",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
] as const;

type SectionName = (typeof SECTION_NAMES)[number];
type SectionMap = Record<SectionName, ContextPressureRecoveryItem[]>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function toItems(value: unknown): ContextPressureRecoveryItem[] {
  if (value === undefined || value === null) return [];
  if (Array.isArray(value)) {
    return value.filter((item): item is ContextPressureRecoveryItem =>
      typeof item === "string" || isObject(item),
    );
  }
  if (typeof value === "string" || isObject(value)) return [value];
  return [];
}

function canonicalize(value: unknown): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw new TypeError("snapshot contains a non-finite number");
    return JSON.stringify(value);
  }
  if (typeof value === "boolean") return value ? "true" : "false";
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
  if (isObject(value)) {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalize(value[key])}`)
      .join(",")}}`;
  }
  throw new TypeError("snapshot contains an unsupported value");
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(canonicalize(value), "utf8").digest("hex");
}

function snapshotDepth(snapshot: WorkingContextSnapshot): number {
  const depth = snapshot.handoffDepth ?? snapshot.depth ?? 0;
  return Number.isFinite(depth) && depth > 0 ? Math.floor(depth) : 0;
}

function isEmptySnapshot(snapshot: WorkingContextSnapshot | null | undefined): boolean {
  if (!snapshot || !isObject(snapshot)) return true;
  return SECTION_NAMES.every((name) => toItems(snapshot[name]).length === 0);
}

/**
 * Projects a bounded, deterministic recovery summary from an existing Working
 * Context snapshot. This function never marks the underlying task complete.
 */
export function recoverContextPressure(
  snapshot: WorkingContextSnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {},
): ContextPressureRecoveryResult {
  const maxDepth = Math.max(0, Math.floor(options.maxDepth ?? 4));
  const maxItemsPerSection = Math.max(0, Math.floor(options.maxItemsPerSection ?? 20));
  const maxItems = Math.max(0, Math.floor(options.maxItems ?? maxItemsPerSection * SECTION_NAMES.length));

  if (!snapshot || !isObject(snapshot)) {
    const result = {
      status: "unknown" as const,
      recovered: false,
      complete: false as const,
      truncated: false,
      sections: {},
      counts: {
        total: 0,
        kept: 0,
        dropped: 0,
        bySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
      },
      reason: "empty-snapshot" as const,
    };
    return { ...result, digest: digestOf(result) };
  }

  const depth = snapshotDepth(snapshot);
  if (depth > maxDepth) {
    const result = {
      status: "depth-exceeded" as const,
      recovered: false,
      complete: false as const,
      truncated: false,
      sections: {},
      counts: {
        total: 0,
        kept: 0,
        dropped: 0,
        bySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
      },
      reason: "depth-exceeded" as const,
    };
    return { ...result, digest: digestOf(result) };
  }

  const source: SectionMap = {
    goal: toItems(snapshot.goal),
    unfinishedWork: toItems(snapshot.unfinishedWork),
    dependencies: toItems(snapshot.dependencies),
    recentEvidence: toItems(snapshot.recentEvidence),
  };
  const total = SECTION_NAMES.reduce((sum, name) => sum + source[name].length, 0);

  if (total === 0) {
    const result = {
      status: "unknown" as const,
      recovered: false,
      complete: false as const,
      truncated: false,
      sections: {},
      counts: {
        total: 0,
        kept: 0,
        dropped: 0,
        bySection: { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 },
      },
      reason: "empty-snapshot" as const,
    };
    return { ...result, digest: digestOf(result) };
  }

  const sections: ContextPressureRecoveryResult["sections"] = {};
  const bySection = { goal: 0, unfinishedWork: 0, dependencies: 0, recentEvidence: 0 };
  let keptTotal = 0;
  let droppedTotal = 0;

  for (const name of SECTION_NAMES) {
    const items = source[name];
    const sectionLimit = Math.min(maxItemsPerSection, Math.max(0, maxItems - keptTotal));
    const keptItems = items.slice(0, sectionLimit);
    const dropped = items.length - keptItems.length;
    sections[name] = { items: keptItems, kept: keptItems.length, dropped };
    bySection[name] = dropped;
    keptTotal += keptItems.length;
    droppedTotal += dropped;
  }

  const result = {
    status: "recovered" as const,
    recovered: true,
    complete: false as const,
    truncated: droppedTotal > 0,
    sections,
    counts: {
      total,
      kept: keptTotal,
      dropped: droppedTotal,
      bySection,
    },
  };
  return { ...result, digest: digestOf(result) };
}

export const recoverFromWorkingContext = recoverContextPressure;
export const recoverWorkingContext = recoverContextPressure;\nexport const projectContextPressureRecovery = recoverContextPressure;

export default recoverContextPressure;

